1: /**
2:  * Resume plan for a {@link LoopRun}.
3:  *
4:  * Translates the persisted task table from a resumed Durable Loop Run
5:  * Tracker into the runtime state the scheduler needs:
6:  *
7:  *   • `replayQueue`     — in-flight tasks that must be re-scheduled
8:  *   • `terminalIds`     — issues already in a terminal phase (done/failed)
9:  *                         plus any `mark-done-pending` tasks that complete
10:  *                         during this call
11:  *   • `resumeIterations`/`resumeSkippedIds` — scheduler progress to
12:  *                         restore so iteration accounting and the
13:  *                         skipped-id allow-list pick up where they left off
14:  *
15:  * `mark-done-pending` tasks — those that finished verification but were
16:  * interrupted before the issue source's `markDone` returned — are
17:  * advanced to `done` here (calling `markDone` first if the source can't
18:  * confirm completion via `isDone`). This keeps the recovery path inside
19:  * one place instead of being inlined in `ralphLoop`.
20:  *
21:  * See ADR-0006 (Durable Loop Run Tracker and stale-run recovery).
22:  */
23: 
24: import type { LoopRun } from "./loop-run.js";
25: import type { RunSnapshot, TaskPhase } from "./state.js";
26: import type { Issue, IssueSource } from "../ralph-loop.js";
27: 
28: export interface ResumePlan {
29:   replayQueue: Issue[];
30:   terminalIds: Set<string | number>;
31:   resumeIterations: number;
32:   resumeSkippedIds: Set<string | number>;
33: }
34: 
35: export async function buildResumePlan(params: {
36:   loopRun: LoopRun;
37:   issueSource: IssueSource;
38: }): Promise<ResumePlan> {
39:   const { loopRun, issueSource } = params;
40:   const initialState = loopRun.snapshot();
41:   const allTasks = Object.values(initialState?.tasks ?? {});
42: 
43:   const terminalIds = new Set<string | number>(
44:     allTasks.filter((task) => isNonRetryableTerminalTaskPhase(task.phase)).map((task) => task.issueId),
45:   );
46: 
47:   // Advance any `mark-done-pending` tasks to `done`, calling the issue
48:   // source's `markDone` first when the source cannot confirm via `isDone`.
49:   const pendingCompletionTasks = allTasks.filter(
50:     (task) => task.phase === "mark-done-pending",
51:   );
52:   for (const task of pendingCompletionTasks) {
53:     const alreadyDone = await issueSource.isDone?.(task.issueId);
54:     if (!alreadyDone) {
55:       await issueSource.markDone({
56:         id: task.issueId,
57:         title: task.title,
58:         body: task.body ?? "",
59:       });
60:     }
61:     loopRun.recordTaskPhase(task.issueId, "done");
62:     terminalIds.add(task.issueId);
63:   }
64: 
65:   // Re-read after the `mark-done-pending → done` writes so scheduler
66:   // progress reflects any tracker updates emitted above.
67:   const refreshedState = loopRun.snapshot();
68:   const replayQueue = refreshedState
69:     ? Object.values(refreshedState.tasks)
70:       .filter((task) => !isTerminalTaskPhase(task.phase) && task.phase !== "mark-done-pending")
71:       .map(toTrackedIssue)
72:     : [];
73: 
74:   return {
75:     replayQueue,
76:     terminalIds,
77:     resumeIterations: refreshedState?.scheduler?.iterationsStarted ?? 0,
78:     resumeSkippedIds: new Set<string | number>(refreshedState?.scheduler?.skippedIds ?? []),
79:   };
80: }
