90: function toTrackedIssue(task: RunSnapshot["tasks"][string]): Issue {
91:   return {
92:     id: task.issueId,
93:     title: task.title || `Issue ${task.issueId}`,
94:     body: task.body ?? "",
95:   };
96: }
