41: const actionLabels: Record<RecoveryChoice, string> = {
42:   resume: "Resume stale run (recover unfinished work)",
43:   rollback: "Rollback and discard loop changes, start fresh",
44:   finishRollback: "Finish partial panic-undo rollback (requires confirmation)",
45:   abandon: "Abandon stale run, start new loop run",
46:   cancel: "Cancel startup, do nothing",
47: };
