57: export function createRecoveryPromptsFromBoundary(boundary: PromptBoundary): RecoveryPrompts {
58:   return {
59:     promptChoice(state, actions) {
60:       return boundary.selectValue(
61:         `Stale loop run detected (runId: ${state.runId}, started by PID ${state.owner.pid})`,
62:         actions.map((action) => ({
63:           label: actionLabels[action],
64:           value: action,
65:           shortcut: actionShortcuts[action],
66:         })),
67:         -1, // no selected default; Enter chooses only the focused option
68:       );
69:     },
70: 
71:     promptDoneInconsistency(task) {
72:       return boundary.selectValue(
73:         `Task #${task.issueId} is marked done but its recorded integrated commit is not reachable from current HEAD.`,
74:         [
75:           { label: `Restart task #${task.issueId} (discard done state)`, value: "restart" },
76:           { label: "Trust tracker and continue (skip task)", value: "trust" },
77:         ],
78:       );
79:     },
80: 
81:     promptDirtyMerge(task) {
82:       return boundary.selectValue(
83:         "Primary repository has uncommitted changes. Merge recovery would overwrite them.",
84:         [
85:           { label: `Clean workspace manually and retry merge recovery for #${task.issueId}`, value: "retry" },
86:           { label: "Abandon stale run", value: "abandon" },
87:         ],
88:       );
89:     },
90: 
91:     promptFinishRollbackConfirm() {
92:       return boundary.selectValue(
93:         "Confirm Finish Rollback. This will discard all loop changes and restore the repository to its pre-loop state.",
94:         [
95:           { label: "Yes, finish rollback", value: "yes", shortcut: "Y" },
96:           { label: "No, cancel", value: "no", shortcut: "N" },
97:         ],
98:       ).then((value) => value === "yes");
99:     },
100:   };
