307:   public async prepareResume(
308:     git: GitClient,
309:     workspaceManager: WorkspaceManager,
310:     prompts: RecoveryPrompts,
311:   ): Promise<void> {
312:     const tasks = Object.values(this.state.tasks);
313: 
314:     for (const task of tasks) {
315:       switch (task.phase) {
316:         case "implementing":
317:           await prepareImplementingResume(task, workspaceManager);
318:           break;
319: 
320:         case "merge-pending":
321:         case "merging":
322:           await prepareMergingResume(task, git, workspaceManager, prompts);
323:           break;
324: 
325:         case "verify-pending":
326:         case "verifying":
327:           console.warn(`  ⚠ Task #${task.issueId} verification was interrupted. Verification will be rerun.`);
328:           break;
329: 
330:         case "mark-done-pending":
331:           console.warn(`  ⚠ Task #${task.issueId} completion marking was interrupted. Completion marking will be retried.`);
332:           break;
333: 
334:         case "done":
335:           if (task.integratedHead) {
336:             const reachable = git.isAncestor(task.integratedHead, "HEAD");
337:             if (!reachable) {
338:               console.warn(
339:                 `\n  ⚠ Task #${task.issueId} is marked done but its integratedHead (${task.integratedHead.slice(0, 8)}) is not reachable from current HEAD.`,
340:               );
341:               console.warn(
342:                 `  The task's integrated changes may have been lost. Manual developer decision required to continue.`,
343:               );
344:               if (prompts === ttyRecoveryPrompts && !process.stdin.isTTY) {
345:                 throw new Error(
346:                   `Inconsistent done state for task #${task.issueId}: integratedHead ${task.integratedHead.slice(0, 8)} not reachable from HEAD. Cannot resume without developer input.`,
347:                 );
348:               }
349:               const decision = await prompts.promptDoneInconsistency(task);
350:               if (decision === "restart") {
351:                 if (this.tracker) {
352:                   this.tracker.restartTask(task.issueId);
353:                   this.state = this.tracker.read() ?? this.state;
354:                 } else {
355:                   task.phase = "scheduled";
356:                   delete task.integratedHead;
357:                   delete task.preMergeHead;
358:                   delete task.lastError;
359:                   // C-4: state-form callers don't get a persisted restart. Production
360:                   // always passes a tracker; this branch only fires in tests using the
361:                   // state-form. Warn loudly so a future caller cannot silently drop the
362:                   // write the way the old code did.
363:                   console.warn(
364:                     `  \u26a0 restartTask called without a tracker for task #${task.issueId}; in-memory state mutated but not persisted. Pass a LoopRunTracker if persistence is required.`,
365:                   );
366:                 }
367:               }
368:             }
369:           }
370:           break;
371:       }
372:     }
373: 
374:     if (this.state.review.phase === "running" || this.state.review.phase === "failed" || this.state.review.phase === "blocked") {
375:       console.warn("  ⚠ Whole-run review was interrupted, failed, or blocked. Review will be rerun.");
376:     }
377:   }
378: }
